// dart format width=80
// ignore_for_file: unused_local_variable, unused_import
// Generated by drift_dev make-migrations; data test written for schema v2.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:datei/core/database/app_database.dart';
import 'package:flutter_test/flutter_test.dart';

import 'generated/schema.dart';

import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // These simple tests verify all possible schema updates with a simple (no
    // data) migration. This is a quick way to ensure that written database
    // migrations properly alter the schema.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = AppDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test('v1 → v2 keeps people and their categories; birth_year_known defaults to true', () async {
    final schema = await verifier.schemaAt(1);
    final oldDb = v1.DatabaseAtV1(schema.newConnection());
    await oldDb.into(oldDb.localUserProfiles).insert(
        v1.LocalUserProfilesCompanion.insert(id: 'me', createdAt: 1, updatedAt: 1));
    await oldDb.into(oldDb.personCategories).insert(v1.PersonCategoriesCompanion.insert(
        id: 'sys:category:family', systemKey: const Value('family'), createdAt: 1, updatedAt: 1));
    await oldDb.into(oldDb.persons).insert(v1.PersonsCompanion.insert(
        id: 'p1', ownerProfileId: 'me', fullName: 'Sara', birthDate: const Value('1996-11-24'),
        createdAt: 1, updatedAt: 1));
    await oldDb.into(oldDb.personCategoryRelations).insert(
        v1.PersonCategoryRelationsCompanion.insert(personId: 'p1', categoryId: 'sys:category:family'));
    await oldDb.close();

    final db = AppDatabase(schema.newConnection());
    await verifier.migrateAndValidate(db, 2);
    final person = await db.select(db.persons).getSingle();
    expect(person.fullName, 'Sara');
    expect(person.birthDate, '1996-11-24');
    expect(person.birthYearKnown, isTrue);
    expect(await db.select(db.personCategoryRelations).get(), hasLength(1));
    expect(await db.select(db.personRelationships).get(), isEmpty);
    await db.close();
  });
}
